      "1302": {
        "meaning": "-krankheit (Suffix)",
        "level": "N3",
        "notes": "Suffix für Krankheitsnamen: 心臓病 (Herzkrankheit), アルツハイマー病 (Alzheimer-Krankheit). Allein steht 病 nicht als びょう; das allgemeine Wort für Krankheit ist 病気（びょうき）.",
        "examples": [
          {
            "japanese": "アルツハイマー病のせいで、色々な事を思い出せない時があります。",
            "romaji": "Arutsuhaimaabyou no sei de, iroiro na koto o omoidasenai toki ga arimasu.",
            "german": "Wegen der Alzheimer-Krankheit kann ich mich manchmal an verschiedene Dinge nicht erinnern."
          },
          {
            "japanese": "祖父は心臓病で入院しています。",
            "romaji": "Sofu wa shinzoubyou de nyuuin shite imasu.",
            "german": "Mein Großvater ist wegen einer Herzkrankheit im Krankenhaus."
          }
        ],
        "pitch": null
      },
