      "1071": {
        "meaning": "duschen; auf sich bekommen; ausgesetzt sein",
        "notes": "Bei 浴びる steht das, was auf den Körper trifft, mit を: シャワーを浴びる (duschen), 日光を浴びる (Sonnenlicht abbekommen). Übertragen sind auch 拍手を浴びる (mit Beifall bedacht werden) und 批判を浴びる (Kritik auf sich ziehen) üblich. Transitives Ichidan-Verb: 浴びます・浴びて・浴びない. Für ein Bad in der Badewanne sagt man meist お風呂に入る.",
        "examples": [
          {
            "japanese": "ウチの犬はシャワーを浴びるのが好きです。",
            "romaji": "Uchi no inu wa shawā o abiru no ga suki desu.",
            "german": "Unser Hund wird gern abgeduscht."
          },
          {
            "japanese": "朝シャワーを浴びます。",
            "romaji": "Asa shawā o abimasu.",
            "german": "Morgens dusche ich."
          },
          {
            "japanese": "歌手は観客の拍手を浴びた。",
            "romaji": "Kashu wa kankyaku no hakushu o abita.",
            "german": "Der Sänger wurde vom Publikum mit Beifall bedacht."
          }
        ],
        "aliases": [
          "あびる"
        ],
        "pitchVariants": [],
        "pitchProvenance": [
          {
            "source": "現代書き言葉UniDic",
            "version": "2025.12; archive SHA256 d94216b589d15d05c408ed59abc5259086703ebbac14e225b5314e4cd106c4db",
            "locator": "https://clrd.ninjal.ac.jp/unidic_archive/2512/unidic-cwj-202512.zip#sys.dic@45561586",
            "attribution": "National Institute for Japanese Language and Linguistics; modified BSD license",
            "patterns": [
              0
            ],
            "finding": "浴びる / アビル; 動詞/一般/*/*; 上一段-バ行; 終止形-一般; lemma 浴びる; aType 0.",
            "match": {
              "word": "浴びる",
              "reading": "あびる",
              "grammaticalForm": "終止形-一般",
              "sense": "JMdict 1547450: transitive ichidan; literal exposure to water/light and figurative reception of applause/criticism."
            }
          }
        ]
      },
