      "2933": {
        "meaning": "wie viele; wie alt",
        "type": "Adverb",
        "level": "N5",
        "notes": "いくつ fragt nach der Anzahl von Dingen, die mit dem allgemeinen Zählwort ～つ gezählt werden. Es fragt auch nach dem Alter: おいくつですか ist höflicher als 何歳ですか. Bei Personen oder besonderen Zählwörtern verwendet man etwa 何人 oder 何枚. Die Kana-Schreibung ist üblich; die Kanji-Schreibung 幾つ wird genauso gelesen.",
        "examples": [
          {
            "japanese": "この箱にりんごが幾つ入っていますか。",
            "romaji": "Kono hako ni ringo ga ikutsu haitte imasu ka.",
            "german": "Wie viele Äpfel sind in dieser Kiste?"
          },
          {
            "japanese": "お子さんはお幾つですか。",
            "romaji": "Okosan wa oikutsu desu ka.",
            "german": "Wie alt ist Ihr Kind?"
          }
        ],
        "aliases": [
          "いくつ"
        ],
        "pitch": null
      },
