        "meaning": "Aus Fehlern lernt man; Misserfolg ist der Weg zum Erfolg",
        "notes": "Übliche Form; もと wird auch 元 geschrieben. Die Variante 失敗は成功の母 („Misserfolg ist die Mutter des Erfolgs“) ist ebenfalls gebräuchlich.",
